echo "K1: dpofix1"
export RUNNER_TRACKING_ID=""
N=/workspace/nox; D=$N/ops/dpo; ts=$(date +%s); W=$(mktemp -d)
base64 -d > $W/char_cycle.sh <<'B64'

B64
base64 -d > $W/mix_data.py <<'B64'

B64
bash -n $W/char_cycle.sh || { echo SYNTAX_FAIL; exit 0; }; python3 -m py_compile $W/mix_data.py || { echo PYFAIL; exit 0; }
echo "body_n_cpu_moe_before=$(P=$(pgrep -f 'llama-server.*8104' | head -1); tr '\0' ' ' </proc/$P/cmdline | grep -o -- '--n-cpu-moe [0-9]*' | awk '{print $2}')"
cp -a $D/char_cycle.sh $D/char_cycle.sh.bak_dpofix_$ts; cp $W/char_cycle.sh $D/char_cycle.sh; cp $W/mix_data.py $D/mix_data.py; chmod +x $D/char_cycle.sh; echo installed
# снять зависшую с 27.11 цепочку (SIGSTOP-тренер без VRAM); kill -9 без trap, чтобы тело не перезапускалось
for P in $(pgrep -f 'char_cycle.sh|python -I train_dpo.py'); do e=$(ps -o etimes= -p $P | tr -d ' '); [ "${e:-0}" -gt 100000 ] && { kill -9 $P && echo "killed_stale $P etimes=$e"; }; done
sleep 2; echo "lock_free=$(flock -n $D/char_cycle.lock true && echo 1 || echo 0) stale_left=$(pgrep -fc 'python -I train_dpo.py')"
cd $D && setsid nohup bash $D/char_cycle.sh >> $N/agent/autotrain/char_cycle.log 2>&1 < /dev/null &
sleep 45
echo "started=$(pgrep -fc 'bash .*char_cycle.sh')"; tail -5 $N/agent/autotrain/char_cycle.log | cut -c1-140
echo "mix: $(grep -h 'mix rows' $D/run7.log | tail -1)"
echo "vram $(nvidia-smi --query-gpu=memory.used,memory.free --format=csv,noheader,nounits)"
rm -rf $W; echo END
